#include <string>
#include <vector>
#include <unordered_map>

class Solution {
public:
    int countOddLetters(int num) {
        std::vector<std::string> ones = {
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
        };
        std::vector<std::string> tens = {
            "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
        };

        auto to_words = [&](auto& self, int n) -> std::string {
            if (n < 20) return ones[n];
            if (n < 100) return tens[n / 10] + (n % 10 ? ones[n % 10] : "");
            if (n < 1000) return ones[n / 100] + "hundred" + (n % 100 ? self(self, n % 100) : "");
            return "";
        };

        std::string s = to_words(to_words, num);
        std::unordered_map<char, int> freq;
        for (char ch : s) freq[ch]++;
        int ans = 0;
        for (auto& p : freq) {
            if (p.second % 2 != 0) ans++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private String[] ones = {
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    };
    private String[] tens = {
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    };

    public int countOddLetters(int num) {
        String s = toWords(num);
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }
        int ans = 0;
        for (int f : freq) {
            if (f % 2 != 0) ans++;
        }
        return ans;
    }

    private String toWords(int n) {
        if (n < 20) return ones[n];
        if (n < 100) return tens[n / 10] + (n % 10 != 0 ? ones[n % 10] : "");
        if (n < 1000) return ones[n / 100] + "hundred" + (n % 100 != 0 ? toWords(n % 100) : "");
        return "";
    }
}

